const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define two polygons for the northern and southern parts of Isabela Island, Galapagos.
    const northIsabela = ee.Geometry.Polygon([[
        [-91.42, 0.05], [-91.35, -0.2], [-91.0, -0.25], 
        [-90.98, -0.05], [-91.15, 0.25], [-91.4, 0.3]
    ]]);
    const southIsabela = ee.Geometry.Polygon([[
        [-91.25, -0.7], [-90.9, -1.05], [-91.3, -1.1], 
        [-91.6, -0.8], [-91.25, -0.7]
    ]]);

    // The question asks for 1:20 am on Jan 7, 2022, Galapagos Time (UTC-6).
    // This corresponds to data collected during the night between Jan 6 and Jan 7.
    // VIIRS passes over around 1:30 am local time. We'll filter for Jan 7, UTC.
    const date = '2022-01-07';

    // 2. Data Acquisition & Check
    let collection = ee.ImageCollection('NOAA/VIIRS/DNB/VNP46A2')
                       .filterDate(date, ee.Date(date).advance(1, 'day'))
                       .select(['DNB_At_Sensor_Radiance_500m']);

    let imageCount = collection.size().getInfo();
    if (imageCount === 0) {
        // Fallback: Check the day before, as collection timing might be off.
        const prevDate = '2022-01-06';
        collection = ee.ImageCollection('NOAA/VIIRS/DNB/VNP46A2')
                       .filterDate(prevDate, ee.Date(prevDate).advance(1, 'day'))
                       .select(['DNB_At_Sensor_Radiance_500m']);
        imageCount = collection.size().getInfo();
    }

    console.log(`Image collection size: ${imageCount}`);
    if (imageCount === 0) {
        console.log(`Evidence: No VIIRS images found for Jan 6-7, 2022 over the area.`);
        console.log('A'); // No lights detected in either region implies they are equal (both zero).
        return;
    }

    const image = collection.mosaic();

    // 3. Processing (Calculate pixel counts to detect C2)
    const scale = 500;
    const northCount = image.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: northIsabela,
        scale: scale,
        maxPixels: 1e9
    }).get('DNB_At_Sensor_Radiance_500m').getInfo();

    const southCount = image.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: southIsabela,
        scale: scale,
        maxPixels: 1e9
    }).get('DNB_At_Sensor_Radiance_500m').getInfo();

    console.log(`Valid Pixels (North): ${northCount}`);
    console.log(`Valid Pixels (South): ${southCount}`);

    if (northCount === 0 || southCount === 0) {
        console.log(`Evidence: No valid pixels in one or both regions after mosaicking.`);
        console.log('C2');
        return;
    }

    // 4. Calculation
    const northMean = image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: northIsabela,
        scale: scale,
        maxPixels: 1e9
    }).get('DNB_At_Sensor_Radiance_500m');

    const southMean = image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: southIsabela,
        scale: scale,
        maxPixels: 1e9
    }).get('DNB_At_Sensor_Radiance_500m');

    // Use evaluate to handle potential nulls gracefully
    const northVal = await ee.Number(northMean).evaluate();
    const southVal = await ee.Number(southMean).evaluate();

    // 5. Validation & Final Answer
    if (northVal === null || southVal === null) {
        console.log(`Evidence: Calculation failed. North: ${northVal}, South: ${southVal}.`);
        console.log('C3');
        return;
    }

    console.log(`Avg Radiance North (nW/cm²/sr): ${northVal.toExponential(3)}`);
    console.log(`Avg Radiance South (nW/cm²/sr): ${southVal.toExponential(3)}`);

    if (northVal > southVal) {
        console.log('Evidence: Northern brightness was greater than southern brightness.');
        console.log('A');
    } else {
        console.log('Evidence: Northern brightness was not greater than southern brightness.');
        console.log('B');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
